import {ThemeProvider, configure} from '@gravity-ui/uikit';
import {AsideHeader, FooterItem, type AsideHeaderItem} from '@gravity-ui/navigation';
import {Gear, House, Moon, Persons, ShoppingCart, Sun} from '@gravity-ui/icons';
import {OrdersPage} from './pages/OrdersPage';
import {StubPage} from './pages/StubPage';

configure({lang: 'ru'});

type PageId = 'home' | 'users' | 'orders' | 'settings';

export function App() {
  const [compact, setCompact] = React.useState(false);
  const [theme, setTheme] = React.useState<'light' | 'dark'>('light');
  const [page, setPage] = React.useState<PageId>('orders');

  const menuItems: AsideHeaderItem[] = React.useMemo(() => [
    {id: 'home', title: 'Главная', icon: House, current: page === 'home', onItemClick: () => setPage('home')},
    ...
  ], [page]);

  return (
    <ThemeProvider theme={theme}>
      <AsideHeader
        logo={{text: 'Админ-панель', icon: ShoppingCart}}
        compact={compact}
        onChangeCompact={setCompact}
        headerDecoration
        menuItems={menuItems}
        renderContent={() => (page === 'orders' ? <OrdersPage /> : <StubPage title={...} />)}
        renderFooter={({compact: c}) => (
          <FooterItem
            id="theme"
            title={theme === 'light' ? 'Тёмная тема' : 'Светлая тема'}
            icon={theme === 'light' ? Moon : Sun}
            compact={c}
            onItemClick={() => setTheme(theme === 'light' ? 'dark' : 'light')}
          />
        )}
      />
    </ThemeProvider>
  );
}
```

